#include "logos_store.h"
#include <cstring>
#include <fstream>
namespace logos {
static std::filesystem::path digest_path(const ObjectStore&s,const Digest256&d,const char*ext){auto h=hex(d);return s.root/h.substr(0,2)/h.substr(2,2)/(h+ext);}static Status read_file(const std::filesystem::path&p,Buffer*out){if(!out)return Status::InvalidArgument;std::ifstream f(p,std::ios::binary);if(!f)return Status::ObjectNotFound;f.seekg(0,std::ios::end);auto n=f.tellg();if(n<0)return Status::IOError;f.seekg(0);out->resize((size_t)n);if(n&&!f.read((char*)out->data(),(std::streamsize)n))return Status::IOError;return Status::Ok;}static Status write_file(const std::filesystem::path&p,ByteSpan b){std::error_code ec;std::filesystem::create_directories(p.parent_path(),ec);if(ec)return Status::IOError;auto tmp=p;tmp+=".tmp";{std::ofstream f(tmp,std::ios::binary|std::ios::trunc);if(!f)return Status::IOError;if(b.size)f.write((const char*)b.data,(std::streamsize)b.size);f.flush();if(!f)return Status::IOError;}if(std::filesystem::exists(p,ec)){std::filesystem::remove(tmp,ec);return Status::Ok;}std::filesystem::rename(tmp,p,ec);if(ec)return Status::IOError;return Status::Ok;}
Status object_store_open(const std::filesystem::path&r,ObjectStore*out){if(!out)return Status::InvalidArgument;std::error_code ec;std::filesystem::create_directories(r,ec);if(ec)return Status::IOError;out->root=r;return Status::Ok;}Status object_put(ObjectStore*s,ByteSpan lgo,Digest256*out){if(!s||!out)return Status::InvalidArgument;auto st=lgo_validate(lgo);if(st!=Status::Ok)return st;LgoObjectView v{};lgo_parse(lgo,&v);auto p=digest_path(*s,v.digest,".lgo");if(std::filesystem::exists(p)){Buffer old;if((st=read_file(p,&old))!=Status::Ok)return st;if(old.size()!=lgo.size||std::memcmp(old.data(),lgo.data,(size_t)lgo.size))return Status::ObjectCollision;*out=v.digest;return Status::Ok;}if((st=write_file(p,lgo))!=Status::Ok)return st;Buffer rb;if((st=read_file(p,&rb))!=Status::Ok)return st;if(rb.size()!=lgo.size||std::memcmp(rb.data(),lgo.data,(size_t)lgo.size))return Status::ObjectCollision;*out=v.digest;return Status::Ok;}Status object_get(const ObjectStore*s,const Digest256&d,Buffer*out){if(!s)return Status::InvalidArgument;auto st=read_file(digest_path(*s,d,".lgo"),out);if(st!=Status::Ok)return st;LgoObjectView v{};st=lgo_parse({out->data(),(u64)out->size()},&v);return st==Status::Ok&&v.digest==d?Status::Ok:Status::BadDigest;}Status object_verify(const ObjectStore*s,const Digest256&d){Buffer b;return object_get(s,d,&b);}Status blob_put(ObjectStore*s,ByteSpan bytes,Digest256*out){if(!s||!out||(!bytes.data&&bytes.size))return Status::InvalidArgument;Digest256 d=sha256(bytes);auto p=digest_path(*s,d,".bin");auto st=write_file(p,bytes);if(st!=Status::Ok)return st;Buffer rb;if((st=read_file(p,&rb))!=Status::Ok)return st;if(rb.size()!=bytes.size||(bytes.size&&std::memcmp(rb.data(),bytes.data,(size_t)bytes.size)))return Status::ObjectCollision;*out=d;return Status::Ok;}Status blob_get(const ObjectStore*s,const Digest256&d,Buffer*out){if(!s)return Status::InvalidArgument;auto st=read_file(digest_path(*s,d,".bin"),out);if(st!=Status::Ok)return st;return sha256({out->data(),(u64)out->size()})==d?Status::Ok:Status::BadDigest;}Status blob_verify(const ObjectStore*s,const Digest256&d){Buffer b;return blob_get(s,d,&b);}
}
